      "theory": "\n            <h4>1. Аддитивная (RGB) и субтрактивная (CMYK) модели</h4>\n            <p>Экраны мониторов излучают свет и работают в аддитивной модели <strong>RGB</strong> (Red, Green, Blue — сумма даёт белый). Печатные машины наносят краску на бумагу в субтрактивной модели <strong>CMYK</strong> (Cyan, Magenta, Yellow, Key/Black). Суммарное покрытие красок (Total Ink Limit) на мелованной бумаге не должно превышать <code>300%</code>.</p>\n            <h4>2. Смесевые краски Pantone</h4>\n            <p>Для идеального попадания в фирменный цвет бренда или печати металликами используется каталог готовых красок <strong>Pantone Solid Coated / Uncoated</strong>.</p>\n        ",
