      "theory": "\n            <h4>1. Антиква, гротеск и акциденция</h4>\n            <p><strong>Антиква (Serif)</strong> имеет засечки и отлично ведёт строку в длинных книжных текстах. <strong>Гротеск (Sans-Serif)</strong> не имеет засечек, чист и универсален в навигации и плакатах. Для гармоничной шрифтовой пары комбинируют контрастные классы (например, выразительный геометрический гротеск в заголовках + нейтральный гуманистический гротеск или антикву в наборе).</p>\n            <h4>2. Кернинг, трекинг и интерлиньяж</h4>\n            <p><strong>Кернинг</strong> — настройка расстояния между конкретной парой букв (например, <code>AV</code>, <code>То</code>). <strong>Трекинг</strong> — равномерная разрядка всего слова. <strong>Интерлиньяж</strong> (межстрочный интервал) для основного текста составляет <code>130%–150%</code> от кегля.</p>\n        ",
