      "theory": "\n            <h4>1. Константы визуальной идентификации</h4>\n            <p>Полноценный логотип поставляется в нескольких версиях: основная горизонтальная, компактная вертикальная, монохромная (чёрная и инверсная белая на тёмном фоне) и упрощённый знак для малых размеров.</p>\n            <h4>2. Охранное поле и недопустимое использование</h4>\n            <p>Вокруг логотипа задаётся неприкосновенное <strong>охранное поле</strong> за модуль <code>X</code> (например, высота заглавной буквы или графического элемента знака), куда запрещено помещать посторонний текст или края листа. В гайдлайне также фиксируются запреты: не растягивать непропорционально, не менять фирменные цвета и не ставить на пёстрый фон без плашки.</p>\n        ",
