      "theory": "\n            <h4>1. Чтение и подготовка крой-штампа (Dieline)</h4>\n            <p>Дизайн коробки создаётся поверх плоской векторной развёртки штанцформы в масштабе <code>1:1</code>. Контур штампа размещается в <strong>отдельном верхнем непечатном или Spot-слое</strong> с атрибутом <code>Overprint Stroke</code>, чтобы ножи не прорезались белой линией на готовой пачке.</p>\n            <h4>2. Обозначение линий и постпечатная отделка</h4>\n            <p>Сплошной линией обозначают <strong>линию вырубки (Cut)</strong>, пунктирной — <strong>линию сгиба/биговки (Crease/Fold)</strong>, штриховкой — клеевой клапан (без лака и краски для схватывания клея!).</p>\n        ",
