      "theory": "\n            <h4>1. Оценка состояния аккумуляторной батареи</h4>\n            <p>Полностью заряженная свинцово-кислотная АКБ после отстоя без нагрузки имеет напряжение разомкнутой цепи (НРЦ) <strong>12.6–12.7 В</strong> (плотность электролита <code>1.27–1.28 г/см³</code>). Под нагрузкой просадка не должна опускаться ниже <code>9.6–10.2 В</code>, а внутреннее сопротивление исправной батареи составляет <code>3–6 мОм</code>.</p>\n            <h4>2. Поиск тока утечки («засыпание» блоков)</h4>\n            <p>Современные электронные блоки автомобиля переходят в спящий режим через <code>15–30 минут</code> после постановки на охрану (с замкнутыми концевиками капота и дверей). Нормальный ток покоя — <strong>20–50 мА (0.02–0.05 А)</strong>. При повышенном потреблении локализацию ведут без выдёргивания предохранителей (чтобы не разбудить CAN-шину!) по милливольтовому падению напряжения на выводах самих предохранителей.</p>\n        ",
