      "theory": "\n            <h4>1. Безопасный поиск короткого замыкания без сжигания пачки предохранителей</h4>\n            <p>Вместо перегорающего предохранителя автоэлектрик подключает мощную галогенную <strong>лампу-ограничитель тока (21/55 Вт)</strong>. Пока короткое замыкание на массу присутствует — лампа горит в полный накал, ограничивая ток безопасными <code>2–4 А</code> и не давая проводке плавиться. Поочерёдно шевеля жгут в переходных гофрах дверей/багажника и отключая промежуточные разъёмы, мастер мгновенно ловит момент погасания лампы!</p>\n            <h4>2. Ремонт автопроводки во влажных зонах</h4>\n            <p>Скрутка на синюю изоленту под днищем или бампером сгнивает в зелёный купорос за одну зиму! Ремонт выполняется только обжимом гильзой кримпером (или аккуратной пайкой с бескислотным флюсом ЛТИ-120/канифолью вне зон изгиба) и герметизацией <strong>термоусадочной трубкой с клеевым подслоем (3:1)</strong> и заменой резиновых уплотнителей пинов разъёма.</p>\n        ",
