      "theory": "\n            <h4>1. Золотое правило безопасности при работе с системой SRS Airbag</h4>\n            <p><strong>КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО</strong> прозванивать пиропатроны подушек безопасности и преднатяжителей ремней мультиметром в режиме омметра! Ток щупов тестера может вызвать детонацию пиропатрона!\n            Перед любыми работами с разъёмами SRS (жёлтая оболочка) необходимо <strong>отключить минусовую клемму АКБ и выждать минимум 3–5 минут</strong> для разряда резервных конденсаторов блока SRS. Для локализации обрыва подрулевого шлейфа («улитки») вместо подушки подключается <strong>контрольный резистор-эмулятор <code>2.0–2.2 Ом</code></strong> и сканером считывается текущее сопротивление контура в Live Data.</p>\n            <h4>2. Диагностика активных (токовых) датчиков скорости колеса ABS/ESP</h4>\n            <p>Современные магниторезистивные датчики ABS питаются напряжением <code>12 В</code> и формируют прямоугольный токовый сигнал (переключение уровней тока <code>7 мА / 14 мА</code>) при вращении магнитного энкодера ступичного подшипника.</p>\n        ",
