      "theory": "\n            <h4>1. Четыре базовых элемента парокомпрессионного цикла</h4>\n            <p>Холод не создаётся — происходит отвод тепла от охлаждаемого объёма наружу. Цикл состоит из 4 узлов:\n            <strong>Компрессор</strong> (сжимает пары хладагента, повышая давление и температуру) → \n            <strong>Конденсатор</strong> (пары конденсируются в жидкость, отдавая тепло окружающей среде) → \n            <strong>Дросселирующее устройство (капиллярная трубка / ТРВ)</strong> (резко снижает давление жидкого хладагента) → \n            <strong>Испаритель</strong> (жидкий хладагент кипит при низком давлении, отбирая тепло у камеры).</p>\n            <h4>2. Кипение и конденсация</h4>\n            <p>Хладагент меняет агрегатное состояние: кипит при отрицательных температурах внутри испарителя и конденсируется при высоких температурах в наружном конденсаторе.</p>\n        ",
