      "theory": "\n            <h4>1. Манометрический коллектор со шкалами температур насыщения</h4>\n            <p>Манометр показывает избыточное давление и соответствующую <strong>температуру кипения/конденсации насыщения</strong> для выбранного фреона.\n            <strong>Синий манометр (НД)</strong> подключается к сервисному порту всасывания компрессора (низкая сторона).\n            <strong>Красный манометр (ВД)</strong> подключается к нагнетанию конденсатора (высокая сторона).</p>\n            <h4>2. Расчёт перегрева (Superheat)</h4>\n            <p><code>Перегрев = Температура трубки всасывания (факт термометром) - Температура кипения по манометру НД</code>.\n            Норма полезного перегрева на выходе из испарителя: <strong>4–8 K (°C)</strong>. Если перегрев равен <code>0 K</code> — испаритель залит жидким фреоном, риск залива компрессора! Если перегрев свыше <code>15 K</code> — нехватка хладагента в системе.</p>\n            <h4>3. Расчёт переохлаждения (Subcooling)</h4>\n            <p><code>Переохлаждение = Температура конденсации по манометру ВД - Температура трубки на выходе конденсатора</code>.\n            Норма переохлаждения: <strong>3–7 K</strong>. Показывает полноту конденсации жидкой фазы перед дросселем.</p>\n        ",
