      "theory": "\n            <h4>1. Конфигурация трёх выводов герметичного компрессора (C-S-R)</h4>\n            <p>Однофазный асинхронный двигатель мотор-компрессора имеет 3 штыревых контакта:\n            <strong>C (Common)</strong> — общая точка;\n            <strong>R (Run / Основная)</strong> — рабочая обмотка низкого сопротивления (обычно <code>10–25 Ом</code>);\n            <strong>S (Start / Пусковая)</strong> — пусковая обмотка более высокого сопротивления (обычно <code>15–40 Ом</code>).\n            Закон сопротивлений: <code>R(S-R) = R(C-S) + R(C-R)</code>. Пробой на корпус проверяется замером мегаомметром между каждым штырём и чистым металлом корпуса (должно быть <code>∞ МОм</code>).</p>\n            <h4>2. Пускозащитные реле</h4>\n            <p><strong>Позисторное реле (PTC)</strong>: таблетка полупроводника в холодном состоянии имеет сопротивление <code>15–30 Ом</code>, пропуская ток на пусковую обмотку S. При пуске таблетка нагревается током, её сопротивление подскакивает до сотен килоом, отключая пусковую обмотку.\n            <strong>Тепловое реле (Klixon)</strong> отключает питание при перегрузке по току или перегреве корпуса компрессора свыше <code>105–120 °C</code>.</p>\n        ",
