      "theory": "\n            <h4>1. Опрессовка сухим азотом (давление до 15–25 бар)</h4>\n            <p><strong>Ни в коем случае нельзя опрессовывать холодильный контур кислородом (взрыв при контакте с маслом!) или воздухом из автокомпрессора (влага убьёт систему!).</strong>\n            Опрессовку проводят строго <strong>сухим азотом</strong> через редуктор: низкая сторона бытового холодильника — до <code>10–12 бар</code> (не более, чтобы не вздуть алюминиевый «плачущий» испаритель в пене!), высокая сторона — до <code>18–25 бар</code>. Выдержка на стабильность давления — не менее 12–24 часов.</p>\n            <h4>2. Методы локализации утечек</h4>\n            <p><strong>Электронный течеискатель</strong> (чувствительность от <code>3–5 г/год</code>) — сканирует пайку и стыки;\n            <strong>Мыльная пена / пенообразующий спрей</strong> — подтверждает точное место выхода пузырей;\n            <strong>Ультрафиолетовый краситель</strong> — вводится в масло, светится неоновым жёлто-зелёным пятном в лучах УФ-фонарика.</p>\n        ",
