      "theory": "\n            <h4>1. Зачем нужно вакуумирование</h4>\n            <p>Продувка фреоном «в воздух» — грубейшее нарушение технологии! В контуре остаётся воздух (неконденсируемый газ, поднимающий давление конденсации и перегружающий мотор) и <strong>влага</strong>. При температуре испарения <code>-20 °C</code> капли воды замерзают на выходе из капилляра в ледяную иглу, наглухо блокируя проход фреона.</p>\n            <h4>2. Физика кипения воды в глубоком вакууме</h4>\n            <p>При атмосферном давлении вода кипит при <code>+100 °C</code>, но при снижении абсолютного давления до <strong>500 микрон рт. ст. (около 67 Па / 0.67 мбар)</strong> температура кипения воды падает до <code>-25 °C</code>! Вся влага внутри контура вскипает и полностью отсасывается насосом в виде пара.\n            Критерий готовности: остаточный вакуум <strong>ниже 500 микрон</strong> с выдержкой теста на натекание (Rise Test) не менее 10 минут.</p>\n        ",
