      "theory": "\n            <h4>1. Комплексная пусконаладка коммерческого холода</h4>\n            <p>Торговое холодильное оборудование (витрины, бонеты, моноблоки холодильных камер) управляется микропроцессорными <strong>электронными контроллерами (Eliwell IDPlus, Carel Easy, Danfoss)</strong> с датчиками температуры NTC/PTC (датчик объема камеры и датчик окончания оттайки испарителя).</p>\n            <h4>2. Итоговый сервисный регламент сдачи оборудования</h4>\n            <p>Ремонт завершается оформлением сервисного акта: проверка питающего напряжения, сопротивления изоляции мегаомметром, опрессовка азотом, глубокое вакуумирование до 500 микрон, точная весовая заправка, программирование параметров контроллера (уставка <code>Set Point</code>, дифференциал <code>diF</code>, интервал оттайки <code>dIt</code>), замер токов компрессора токовыми клещами и достижение рабочей температуры в объёме витрины.</p>\n        ",
