      "theory": "\n            <h4>1. Замер компрессии бензинового ДВС</h4>\n            <p>Условия правильного замера: двигатель прогрет до рабочей температуры <code>80–90 °C</code>, все свечи выкручены, аккумулятор полностью заряжен, дроссельная заслонка <strong>полностью открыта</strong>. Норма для современных двигателей — <strong>12–14 бар</strong>, разброс между цилиндрами — не более <code>1.0 бар</code>.</p>\n            <h4>2. Масляная проба и пневмотестирование (Leak-Down Test)</h4>\n            <p>Если компрессия во 2-м цилиндре просела до <code>7 бар</code>, в свечное отверстие заливают <code>10–15 мл</code> моторного масла:\n            - Если компрессия подскочила до 12 бар — изношены или залегли <strong>поршневые кольца</strong>;\n            - Если компрессия не изменилась — негерметичны <strong>клапаны ГРМ</strong> или пробита прокладка ГБЦ.\n            <strong>Пневмотестер</strong> подает сжатый воздух <code>4–6 бар</code> в цилиндр при ВМТ такта сжатия: выход воздуха в глушитель указывает на выпускной клапан, во впускной коллектор — на впускной клапан, в расширительный бачок (пузыри) — на пробой прокладки ГБЦ, в маслозаливную горловину — на износ колец/поршня.</p>\n        ",
