      "summary": "Оформите дефектовочную ведомость блока цилиндров и коленвала: замеры 1-го цилиндра нутромером (овальность 0.06 мм, конусность 0.08 мм при допуске 0.03 мм), замер шеек коленвала микрометром и проверка зазора вкладыша нитью Plastigauge (0.038 мм). Назначьте ремонтные работы.",
      "theory": "\n            <h4>1. Замер цилиндров нутромером на овальность и конусность</h4>\n            <p>Нутромер настраивается по микрометру на номинальный диаметр цилиндра. Промеры гильзы делают в <strong>трёх поясах по высоте</strong> (верх — зона остановки верхнего компрессионного кольца с максимальной выработкой; середина; низ) и в <strong>двух взаимно перпендикулярных плоскостях</strong> (продольной оси двигателя и поперечной упорной плоскости юбки поршня).\n            - <strong>Овальность</strong>: разница диаметров в одной плоскости (предел <code>0.03–0.05 мм</code>);\n            - <strong>Конусность</strong>: разница между верхним и нижним поясом. При превышении допусков блок растачивается в ремонтный размер (<code>+0.25 / +0.50 мм</code>).</p>\n            <h4>2. Контроль масляного зазора коленвала с помощью Plastigauge</h4>\n            <p>Пластиковая калиброванная нить Plastigauge укладывается на чистую сухую шейку вала. Крышка подшипника затягивается строго по мануалу <strong>динамометрическим ключом с доворотом угла</strong>. Вал <em>категорически нельзя проворачивать</em>! Крышка снимается, и ширина сплющенной полоски измеряется по калибровочной шкале. Норма масляного зазора шатунных и коренных вкладышей: <strong>0.025–0.050 мм</strong>.</p>\n        ",
