      "theory": "\n            <h4>1. Механический замер давления масла</h4>\n            <p>Датчик аварийного давления масла («маслёнка») срабатывает слишком поздно — при падении до <code>0.3–0.6 бар</code>, когда мотор уже испытывает масляное голодание!\n            Механический манометр вкручивается вместо штатного датчика.\n            Норма давления прогретого масла (90–100 °C):\n            - На холостом ходу (800 об/мин): не менее <strong>1.2–1.8 бар</strong>;\n            - На 3000 об/мин: <strong>3.5–4.5 бар</strong> (срабатывание редукционного клапана насоса). Причины низкого давления: износ вкладышей коленвала, заклинивание редукционного клапана, закоксовка сетки маслоприёмника.</p>\n            <h4>2. Опрессовка и тест системы охлаждения</h4>\n            <p>Проверка на микротечи: ручным насосом с адаптером в радиатор/бачок нагнетают давление <strong>1.2–1.5 бар</strong> (не превышая номинала крышки!). Падение стрелки указывает на течь радиатора, помпы, патрубков или термостата. Плотность и температуру замерзания этиленгликоля (норма <code>-40 °C</code>) проверяют оптическим <strong>рефрактометром</strong>.</p>\n        ",
