      "theory": "\n            <h4>1. Методика дефектовки шарниров подвески</h4>\n            <p>- <strong>Шаровые опоры</strong>: проверяются монтажкой под нагрузкой и в вывешенном состоянии. Осевой люфт пальца свыше <code>0.8–1.0 мм</code> опасен риском вырывания пальца из корпуса на ходу!\n            - <strong>Сайлентблоки</strong>: осматриваются на отслоение резины от металлической обоймы, трещины и внутреннее смещение втулки.\n            - <strong>Золотое правило затяжки подвески</strong>: все болты сайлентблоков и рычагов затягиваются <em>строго в положении автомобиля на колёсах под статической нагрузкой веса (в снаряжённом состоянии)</em>! Затяжка на вывешенном подъемнике скручивает резину в покое и рвёт сайлентблок за 2–3 тысячи километров.</p>\n            <h4>2. Диагностика двухрядных ступичных подшипников</h4>\n            <p>Гул ступичного подшипника проверяется на вывешенном колесе вращением пружины стойки рукой: при вращении колеса в витках пружины ощущается микровибрация («перекат» шариков по раковинам обоймы). Осевой люфт проверяется часовым индикатором (допуск до <code>0.03–0.05 мм</code>).</p>\n        ",
