      "theory": "\n            <h4>1. Контроль толщины и торцевого биения тормозных дисков</h4>\n            <p>При жалобе на вибрацию и биение педали тормоза при торможении со скорости <code>80–120 км/ч</code> индикатором часового типа замеряют <strong>торцевое биение рабочей поверхности диска</strong> на расстоянии 10 мм от края. Предельно допустимое биение — <strong>не более 0.04–0.05 мм</strong>! Также микрометром в 8 точках замеряют разнотолщинность диска (DTV, допуск не более <code>0.015 мм</code>) и сравнивают толщину с клеймом <code>Min TH (Minimum Thickness)</code> на торце диска.</p>\n            <h4>2. Ревизия суппортов и замена тормозной жидкости</h4>\n            <p>Направляющие пальцы очищаются и смазываются специальной синтетической полигликолевой смазкой (обычная литиевая или медная смазка разъедает резиновые пыльники!). Тормозная жидкость DOT 4 гигроскопична: при содержании влаги свыше <code>3%</code> температура кипения падает с <code>230 °C</code> до опасных <code>150 °C</code> (риск образования паровых пробок и полного провала педали при затяжном спуске!). Прокачка систем с гидроблоком ABS выполняется под давлением <code>1.5–2.0 бар</code>.</p>\n        ",
